function turretWorld() {
  const world = new World([], [], 8);
  const owner = createTank(
    100,
    {
      ...STARTER,
      id: 'turret',
      avatar: false,
      life: 100,
      speed: 0,
      parts: [STARTER.parts[0], { ...STARTER.parts[1], type: 4032 }],
    },
    'enemy',
